export function RadiusToken({
  name = "{{name}}",
  value = {{value}},
  shape = "{{shape}}",
  accent = "{{accent}}",
}) {
  let el;
  if (shape === "box") el = <span style={{ width: 56, height: 56, borderRadius: value, background: accent, boxSizing: "border-box" }} />;
  else if (shape === "button") el = <span style={{ padding: "12px 18px", borderRadius: value, background: accent, fontWeight: 600, fontSize: 13, boxSizing: "border-box" }}>Button</span>;
  else el = <span style={{ width: 48, height: 48, borderRadius: value, background: accent, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, boxSizing: "border-box" }}>A</span>;
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <code style={{ display: "block", marginBottom: 14, padding: "8px 10px", background: "#24143012", borderRadius: 6, font: "12px/1.4 ui-monospace, monospace" }}>--{name}: {value}px;</code>
      <div style={{ display: "flex", alignItems: "center", gap: 12, height: 64 }}>{el}</div>
      <p style={{ margin: "10px 0 0", fontSize: 11, color: "#24143099" }}>shown on: {shape}</p>
    </div>
  );
}
